SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM PARTICIPANT
WHERE ROOM_ID = #{gameId}
  AND NICKNAME = #{playerName}

SELECT COUNT(*) + 1
FROM PARTICIPANT
WHERE ROOM_ID = #{gameId}

mapper.update:
UPDATE PARTICIPANT
SET LEFT_AT = SYSTIMESTAMP, IS_READY = 'N', IS_HOST = 'N'
WHERE ROOM_ID = #{gameId}
  AND PARTICIPANT_ID = #{playerId}

UPDATE PARTICIPANT
SET IS_HOST = CASE WHEN PARTICIPANT_ID = #{hostPlayerId} THEN 'Y' ELSE 'N' END
WHERE ROOM_ID = #{gameId}

UPDATE GAME_PARTICIPANT
SET IS_WINNER = #{winner}
WHERE PARTICIPANT_ID = #{participantId}
